"""Builds the GitHub Pages site for presets: index.toml, the preset files and a small index.html.

Each preset has one vote issue titled "Vote: <file>" with the preset-vote label; its 👍 count is the
vote total. Missing vote issues are created. Without GH_TOKEN it runs offline with zero votes.

Usage: build_index.py <presets dir> <output dir>
"""
import html, json, os, pathlib, shutil, sys, urllib.error, urllib.request

LABEL = "preset-vote"
src, out = pathlib.Path(sys.argv[1]), pathlib.Path(sys.argv[2])
repo, token = os.environ.get("REPO", "luanfernandes/eqloadout"), os.environ.get("GH_TOKEN")
API = f"https://api.github.com/repos/{repo}"


def api(method, path, body=None):
    req = urllib.request.Request(
        API + path,
        method=method,
        data=json.dumps(body).encode() if body is not None else None,
        headers={"Authorization": f"Bearer {token}", "Accept": "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28"},
    )
    with urllib.request.urlopen(req) as r:
        return json.load(r)


def meta(text):
    m = {}
    for line in text.splitlines():
        if not line.startswith("#"):
            break
        key, sep, value = line[1:].partition(":")
        if sep:
            m.setdefault(key.strip(), value.strip())
    return m


def vote_issues():
    try:
        api("GET", f"/labels/{LABEL}")
    except urllib.error.HTTPError as e:
        if e.code != 404:
            raise
        api("POST", "/labels", {"name": LABEL, "color": "a6ff3d", "description": "React with 👍 to vote for this preset"})
    found, page = {}, 1
    while True:
        batch = api("GET", f"/issues?labels={LABEL}&state=all&per_page=100&page={page}")
        for i in batch:
            if "pull_request" not in i and i["title"].startswith("Vote: "):
                found.setdefault(i["title"][len("Vote: "):], i)
        if len(batch) < 100:
            return found
        page += 1


def toml_str(s):
    return json.dumps(s, ensure_ascii=True)  # JSON string escapes are valid TOML basic strings


issues = vote_issues() if token else {}
out.mkdir(parents=True, exist_ok=True)
entries = []
for path in sorted(src.glob("eql-*.txt")):
    text = path.read_text(encoding="ascii")
    m = meta(text)
    game = m.get("game", "(any)")
    issue = issues.get(path.name)
    if token and issue is None:
        title = f"{game} - {m['name']}" if game != "(any)" else m["name"]
        body = (
            f"**{title}** (`{path.name}`)\n\n{m.get('notes', '')}\n\n"
            "React with 👍 to vote for this preset. Votes are counted once a day and decide the order in "
            "EQ Loadout's **Get presets** list. Comments with feedback or tweaks are welcome.\n\n"
            f"```\n{text}```\n"
        )
        issue = api("POST", "/issues", {"title": f"Vote: {path.name}", "body": body, "labels": [LABEL]})
        print("created vote issue", issue["html_url"])
    votes = issue["reactions"]["+1"] if issue else 0
    entries.append((votes, path.name, m, issue["html_url"] if issue else None))
    shutil.copy(path, out / path.name)

entries.sort(key=lambda e: (-e[0], e[2].get("game", "(any)") == "(any)", e[2].get("game", ""), e[2]["name"]))
lines = ["# Generated by .github/scripts/build_index.py", ""]
rows = []
for votes, name, m, url in entries:
    lines += ["[[presets]]", f"file = {toml_str(name)}", f"name = {toml_str(m['name'])}"]
    if m.get("game", "(any)") != "(any)":
        lines.append(f"game = {toml_str(m['game'])}")
    lines += [f"notes = {toml_str(m.get('notes', ''))}", f"votes = {votes}"]
    if url:
        lines.append(f"vote_url = {toml_str(url)}")
    lines.append("")
    game = m.get("game", "(any)")
    game = "Any game" if game == "(any)" else game
    vote = f'<a class="small" href="{html.escape(url)}">Vote 👍</a>' if url else ""
    search = html.escape(f"{game} {m['name']} {m.get('notes', '')}".lower())
    rows.append(
        f'      <article class="preset" data-search="{search}"><h3>{html.escape(game)}</h3>'
        f'<div class="label">{html.escape(m["name"])}</div><p>{html.escape(m.get("notes", ""))}</p>'
        f'<div class="row"><span class="votes"><b>{votes}</b> votes</span>{vote}'
        f'<a class="small" href="{name}" download>Download</a></div></article>'
    )
(out / "index.toml").write_text("\n".join(lines), encoding="utf-8")

root = pathlib.Path(__file__).resolve().parents[2]
page = (root / ".github" / "site" / "index.html").read_text(encoding="utf-8")
page = page.replace("{{PRESETS}}", "\n".join(rows)).replace("{{COUNT}}", str(len(entries))).replace("{{REPO}}", repo)
(out / "index.html").write_text(page, encoding="utf-8")
for asset in ("logo.svg", "social.png"):
    shutil.copy(root / "docs" / "brand" / asset, out / asset)
print(f"{len(entries)} presets written to {out}")
